CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL);
CREATE TABLE sessions (sid varchar PRIMARY KEY, sess json NOT NULL, expire timestamp NOT NULL);
CREATE INDEX sessions_expire ON sessions(expire);
CREATE TABLE tenants (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE companies (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, name text NOT NULL, currency text NOT NULL DEFAULT 'PHP' CHECK(currency='PHP'), timezone text NOT NULL DEFAULT 'Asia/Manila', theme jsonb NOT NULL DEFAULT '{"mode":"light","preset":"ocean"}', UNIQUE(tenant_id,id));
CREATE TABLE memberships (user_id uuid REFERENCES users, tenant_id uuid NOT NULL, company_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('owner','accountant','auditor')), PRIMARY KEY(user_id,company_id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
CREATE FUNCTION scoped(t uuid, c uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT t = nullif(current_setting('app.tenant',true),'')::uuid AND c = nullif(current_setting('app.company',true),'')::uuid AND EXISTS(SELECT 1 FROM memberships WHERE user_id = nullif(current_setting('app.user',true),'')::uuid AND tenant_id=t AND company_id=c) $$;
ALTER TABLE companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE companies FORCE ROW LEVEL SECURITY;
CREATE POLICY company_scope ON companies USING (EXISTS(SELECT 1 FROM memberships m WHERE m.company_id=id AND m.user_id=nullif(current_setting('app.user',true),'')::uuid));
CREATE TABLE branches (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, name text NOT NULL, UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE branches ENABLE ROW LEVEL SECURITY;
ALTER TABLE branches FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON branches USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX branches_scope ON branches(tenant_id,company_id);
CREATE TABLE periods (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, name text NOT NULL, starts date NOT NULL, ends date NOT NULL, closed boolean NOT NULL DEFAULT false, CHECK(starts<=ends), EXCLUDE USING gist (company_id WITH =, daterange(starts,ends,'[]') WITH &&), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE periods ENABLE ROW LEVEL SECURITY;
ALTER TABLE periods FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON periods USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX periods_scope ON periods(tenant_id,company_id);
CREATE TABLE accounts (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, code text NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('asset','liability','equity','income','expense')), active boolean NOT NULL DEFAULT true, UNIQUE(company_id,code), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounts FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON accounts USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX accounts_scope ON accounts(tenant_id,company_id);
CREATE TABLE tax_rules (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, code text NOT NULL, name text NOT NULL, rate numeric(6,4) NOT NULL CHECK(rate BETWEEN 0 AND 1), verified boolean NOT NULL DEFAULT false CHECK(verified=false), effective_from date NOT NULL, UNIQUE(company_id,code), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE tax_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE tax_rules FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON tax_rules USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX tax_rules_scope ON tax_rules(tenant_id,company_id);
CREATE TABLE parties (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('customer','supplier')), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE parties ENABLE ROW LEVEL SECURITY;
ALTER TABLE parties FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON parties USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX parties_scope ON parties(tenant_id,company_id);
CREATE TABLE journals (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, number bigint GENERATED ALWAYS AS IDENTITY, business_date date NOT NULL, memo text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted')), reversal_of uuid, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,reversal_of) REFERENCES journals(tenant_id,company_id,id), UNIQUE(company_id,reversal_of), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE journals ENABLE ROW LEVEL SECURITY;
ALTER TABLE journals FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON journals USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX journals_scope ON journals(tenant_id,company_id);
CREATE TABLE journal_lines (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, journal_id uuid NOT NULL, account_id uuid NOT NULL, debit numeric(20,2) NOT NULL DEFAULT 0, credit numeric(20,2) NOT NULL DEFAULT 0, CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)), FOREIGN KEY(tenant_id,company_id,journal_id) REFERENCES journals(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,account_id) REFERENCES accounts(tenant_id,company_id,id), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE journal_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE journal_lines FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON journal_lines USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX journal_lines_scope ON journal_lines(tenant_id,company_id);
CREATE TABLE documents (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, number bigint GENERATED ALWAYS AS IDENTITY, kind text NOT NULL CHECK(kind IN ('sale','bill')), party_id uuid NOT NULL, party_name text NOT NULL, description text NOT NULL, business_date date NOT NULL, net numeric(20,2) NOT NULL CHECK(net>0), tax numeric(20,2) NOT NULL CHECK(tax>=0), gross numeric(20,2) NOT NULL CHECK(gross=net+tax), tax_code text NOT NULL, tax_rate numeric(6,4) NOT NULL, journal_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,company_id,party_id) REFERENCES parties(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,journal_id) REFERENCES journals(tenant_id,company_id,id), UNIQUE(company_id,journal_id), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE documents FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON documents USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX documents_scope ON documents(tenant_id,company_id);
CREATE TABLE payments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, document_id uuid NOT NULL, business_date date NOT NULL, cash numeric(20,2) NOT NULL CHECK(cash>=0), withholding numeric(20,2) NOT NULL CHECK(withholding>=0), reference text NOT NULL, journal_id uuid NOT NULL, CHECK(cash+withholding>0), FOREIGN KEY(tenant_id,company_id,document_id) REFERENCES documents(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id,journal_id) REFERENCES journals(tenant_id,company_id,id), UNIQUE(company_id,journal_id), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE payments FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON payments USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX payments_scope ON payments(tenant_id,company_id);
CREATE TABLE audit_events (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users, action text NOT NULL, entity_id uuid NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON audit_events USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX audit_events_scope ON audit_events(tenant_id,company_id);
CREATE TABLE outbox (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, event_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE outbox ENABLE ROW LEVEL SECURITY;
ALTER TABLE outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON outbox USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX outbox_scope ON outbox(tenant_id,company_id);
CREATE TABLE requests (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, company_id uuid NOT NULL, key text NOT NULL, hash text NOT NULL, response jsonb NOT NULL, UNIQUE(company_id,key), UNIQUE(tenant_id,company_id,id), FOREIGN KEY(tenant_id,company_id) REFERENCES companies(tenant_id,id));
ALTER TABLE requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE requests FORCE ROW LEVEL SECURITY;
CREATE POLICY scope ON requests USING (scoped(tenant_id,company_id)) WITH CHECK (scoped(tenant_id,company_id));
CREATE INDEX requests_scope ON requests(tenant_id,company_id);

CREATE INDEX lines_journal ON journal_lines(journal_id);
CREATE INDEX payments_document ON payments(document_id);
CREATE FUNCTION protect_posted() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE j uuid; s text;
BEGIN
 IF TG_TABLE_NAME='journals' THEN
   IF TG_OP='INSERT' AND NEW.status='posted' THEN RAISE EXCEPTION 'Create drafts before posting'; END IF;
   IF TG_OP<>'INSERT' AND OLD.status='posted' THEN RAISE EXCEPTION 'Posted journals are immutable'; END IF;
 ELSE
   IF TG_OP='UPDATE' AND (NEW.journal_id<>OLD.journal_id OR NEW.company_id<>OLD.company_id OR NEW.tenant_id<>OLD.tenant_id) THEN RAISE EXCEPTION 'Cannot move journal lines'; END IF;
   IF TG_OP='DELETE' THEN j=OLD.journal_id; ELSE j=NEW.journal_id; END IF;
   SELECT status INTO s FROM journals WHERE id=j FOR UPDATE;
   IF s='posted' THEN RAISE EXCEPTION 'Posted journal lines are immutable'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
CREATE TRIGGER immutable_header BEFORE INSERT OR UPDATE OR DELETE ON journals FOR EACH ROW EXECUTE FUNCTION protect_posted();
CREATE TRIGGER immutable_lines BEFORE INSERT OR UPDATE OR DELETE ON journal_lines FOR EACH ROW EXECUTE FUNCTION protect_posted();
CREATE FUNCTION validate_posting() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE n int; balance numeric; p uuid;
BEGIN
 IF NEW.status='posted' THEN
   SELECT id INTO p FROM periods WHERE company_id=NEW.company_id AND NEW.business_date BETWEEN starts AND ends AND NOT closed FOR UPDATE;
   IF p IS NULL THEN RAISE EXCEPTION 'No open fiscal period'; END IF;
   SELECT count(*),sum(debit-credit) INTO n,balance FROM journal_lines WHERE journal_id=NEW.id;
   IF n<2 OR balance<>0 THEN RAISE EXCEPTION 'Journal must have balanced debit and credit lines'; END IF;
   IF EXISTS(SELECT 1 FROM journal_lines l JOIN accounts a ON a.id=l.account_id WHERE l.journal_id=NEW.id AND NOT a.active) THEN RAISE EXCEPTION 'Inactive account'; END IF;
 END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT OR UPDATE ON journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_posting();
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial and audit records are append-only'; END $$;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON documents FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_record();

CREATE FUNCTION provision_company(u uuid, company_name text, start_date date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t uuid:=gen_random_uuid(); c uuid:=gen_random_uuid();
BEGIN
 IF u IS DISTINCT FROM nullif(current_setting('app.user',true),'')::uuid THEN RAISE EXCEPTION 'Unauthorized'; END IF;
 INSERT INTO tenants VALUES(t,company_name);
 INSERT INTO companies(id,tenant_id,name) VALUES(c,t,company_name);
 INSERT INTO memberships VALUES(u,t,c,'owner');
 INSERT INTO branches VALUES(gen_random_uuid(),t,c,'Main branch');
 INSERT INTO periods(id,tenant_id,company_id,name,starts,ends) VALUES(gen_random_uuid(),t,c,'FY '||extract(year from start_date),date_trunc('year',start_date)::date,(date_trunc('year',start_date)+interval '1 year - 1 day')::date);
 INSERT INTO accounts(id,tenant_id,company_id,code,name,kind) SELECT gen_random_uuid(),t,c,code,name,kind FROM (VALUES
 ('1000','Cash and bank','asset'),('1100','Accounts receivable','asset'),('1200','Input VAT','asset'),('1300','Creditable withholding tax','asset'),('2000','Accounts payable','liability'),('2100','Output VAT','liability'),('2200','Withholding tax payable','liability'),('3000','Owner equity','equity'),('4000','Service and sales revenue','income'),('5000','Operating expenses','expense')) a(code,name,kind);
 INSERT INTO tax_rules(id,tenant_id,company_id,code,name,rate,effective_from) VALUES(gen_random_uuid(),t,c,'DEMO_VAT','Sample 12% VAT — unverified',0.12,start_date),(gen_random_uuid(),t,c,'DEMO_NONE','Sample no VAT — unverified',0,start_date);
 RETURN c;
END $$;
REVOKE ALL ON FUNCTION provision_company(uuid,text,date) FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO tala_app;
GRANT SELECT,INSERT ON users TO tala_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON sessions TO tala_app;
GRANT SELECT ON memberships,tenants,companies TO tala_app;
GRANT UPDATE(theme) ON companies TO tala_app;
GRANT EXECUTE ON FUNCTION provision_company(uuid,text,date) TO tala_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO tala_app;
GRANT SELECT,INSERT ON branches TO tala_app;
GRANT SELECT,INSERT ON periods TO tala_app;
GRANT SELECT,INSERT ON accounts TO tala_app;
GRANT SELECT,INSERT ON tax_rules TO tala_app;
GRANT SELECT,INSERT ON parties TO tala_app;
GRANT SELECT,INSERT ON journals TO tala_app;
GRANT SELECT,INSERT ON journal_lines TO tala_app;
GRANT SELECT,INSERT ON documents TO tala_app;
GRANT SELECT,INSERT ON payments TO tala_app;
GRANT SELECT,INSERT ON audit_events TO tala_app;
GRANT SELECT,INSERT ON outbox TO tala_app;
GRANT SELECT,INSERT ON requests TO tala_app;
GRANT UPDATE(status) ON journals TO tala_app;
GRANT UPDATE(closed) ON periods TO tala_app;
